//! Cypher for Neo4j and FalkorDB (`docs/graphify-exports.md` §10): Graphify's `cypher.txt`
//! byte for byte, and the node and relationship records its `--push` loads, which name labels
//! and relationship types differently from the file.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::fs;
use std::io::{self, BufWriter, Write};
use std::path::Path;

use crate::nx::{Attr, Attrs, NxGraph};
use anyhow::{Context, Result};

pub const CYPHER_FILE: &str = "cypher.txt";

/// The file's first line (Graphify writes `generated by /graphify`).
pub const HEADER: &str = "// Neo4j Cypher import - generated by dijkstral";

/// Python's `str.capitalize`: the first character in title case, the rest in lower case.
fn capitalize(s: &str) -> String {
    let mut chars = s.chars();
    let Some(first) = chars.next() else {
        return String::new();
    };
    let mut out = String::with_capacity(s.len());
    if first == 'ŉ' {
        // Title case keeps the letter after the apostrophe upper case.
        out.push_str("ʼN");
    } else {
        // Title case is upper case except that a multi-character upper case form keeps only
        // its first character upper (ß → Ss, ﬀ → Ff).
        let mut up = first.to_uppercase();
        if let Some(c) = up.next() {
            out.push(c);
        }
        for c in up {
            out.extend(c.to_lowercase());
        }
    }
    out.push_str(&chars.as_str().to_lowercase());
    out
}

fn ascii_word(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// A value as text: strings as they are, anything else as JSON (Graphify fails on them).
fn text(v: &Attr) -> String {
    match v {
        Attr::Str(s) => s.to_string(),
        other => other.json_text(),
    }
}

/// The node label in `cypher.txt`: `file_type` (`unknown` when absent or empty), capitalised,
/// keeping only `[A-Za-z0-9_]`; `Entity` unless that starts with an ASCII letter.
pub fn file_label(file_type: Option<&Attr>) -> String {
    let t = match file_type {
        None | Some(Attr::Null) => "unknown".to_string(),
        Some(v) => match text(v) {
            s if s.is_empty() => "unknown".to_string(),
            s => s,
        },
    };
    let t: String = capitalize(&t).chars().filter(|&c| ascii_word(c)).collect();
    if t.starts_with(|c: char| c.is_ascii_alphabetic()) {
        t
    } else {
        "Entity".into()
    }
}

/// The relationship type in `cypher.txt`: `relation` upper-cased, keeping only `[A-Z0-9_]`;
/// `RELATES_TO` unless that starts with a letter.
pub fn file_type(relation: Option<&Attr>) -> String {
    let r = relation.map(text).unwrap_or_default();
    let r: String = r
        .to_uppercase()
        .chars()
        .filter(|&c| ascii_word(c))
        .collect();
    if r.starts_with(|c: char| c.is_ascii_alphabetic()) {
        r
    } else {
        "RELATES_TO".into()
    }
}

/// A single-quoted Cypher string body: characters below U+0020 other than tab removed, then
/// `\` and `'` backslash-escaped.
pub fn escape(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\'' => out.push_str("\\'"),
            '\t' => out.push('\t'),
            c if c < ' ' => {}
            c => out.push(c),
        }
    }
}

/// `cypher.txt`: a header, a blank line, one `MERGE` per node in node order, a blank line, one
/// `MATCH … MERGE` per edge in `G.edges()` order with the edge's own direction, joined by
/// newlines (so no trailing newline after the last edge).
pub fn write_to(g: &NxGraph, w: &mut impl Write) -> io::Result<()> {
    // Statements are built in a buffer written out in large pieces.
    let mut out = String::with_capacity(1 << 17);
    let flush = |out: &mut String, w: &mut dyn Write| -> io::Result<()> {
        if out.len() >= 1 << 16 {
            w.write_all(out.as_bytes())?;
            out.clear();
        }
        Ok(())
    };
    out.push_str(HEADER);
    out.push('\n');
    for n in &g.nodes {
        let label = match n.attrs.get("label") {
            Some(Attr::Null) | None => n.id.clone(),
            Some(v) => text(v),
        };
        let _ = write!(
            out,
            "\nMERGE (n:{} {{id: '",
            file_label(n.attrs.get("file_type"))
        );
        escape(&n.id, &mut out);
        out.push_str("', label: '");
        escape(&label, &mut out);
        out.push_str("'});");
        flush(&mut out, w)?;
    }
    out.push('\n');
    for (_, _, e) in g.edge_walk() {
        let edge = &g.edges[e as usize];
        let conf = edge
            .attrs
            .get("confidence")
            .map_or_else(|| "EXTRACTED".to_string(), text);
        out.push_str("\nMATCH (a {id: '");
        escape(&g.nodes[edge.source as usize].id, &mut out);
        out.push_str("'}), (b {id: '");
        escape(&g.nodes[edge.target as usize].id, &mut out);
        let _ = write!(
            out,
            "'}}) MERGE (a)-[:{} {{confidence: '",
            file_type(edge.attrs.get("relation"))
        );
        escape(&conf, &mut out);
        out.push_str("'}]->(b);");
        flush(&mut out, w)?;
    }
    w.write_all(out.as_bytes())
}

/// `cypher.txt` as a string.
pub fn render(g: &NxGraph) -> String {
    let mut out = Vec::new();
    write_to(g, &mut out).expect("writing to memory");
    String::from_utf8(out).expect("UTF-8 in, UTF-8 out")
}

pub fn write(g: &NxGraph, path: &Path) -> Result<()> {
    let file = fs::File::create(path).with_context(|| format!("writing {}", path.display()))?;
    let mut w = BufWriter::new(file);
    write_to(g, &mut w)
        .and_then(|()| w.flush())
        .with_context(|| format!("writing {}", path.display()))
}

// ---------------------------------------------------------------------------------------------
// --push

/// A property value the push stores: strings, integers, floats and booleans; Graphify drops
/// `null`, lists and objects.
#[derive(Debug, Clone, PartialEq)]
pub enum Prop {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
}

pub type Props = Vec<(String, Prop)>;

/// The node label `--push` uses: `file_type` capitalised, keeping only `[A-Za-z0-9_]`;
/// `Entity` when nothing is left. (Graphify's push sends a label starting with a digit as it
/// is, which Neo4j and FalkorDB reject; dijkstral quotes every name, so it loads.)
pub fn push_label(file_type: Option<&Attr>) -> String {
    let t = file_type.map(text).unwrap_or_default();
    let t: String = capitalize(&t).chars().filter(|&c| ascii_word(c)).collect();
    if t.is_empty() {
        "Entity".into()
    } else {
        t
    }
}

/// The relationship type `--push` uses: `relation` upper-cased with every character outside
/// `[A-Z0-9_]` replaced by `_`; `RELATED_TO` when empty.
pub fn push_type(relation: Option<&Attr>) -> String {
    let r = relation.map(text).unwrap_or_default();
    let r: String = r
        .to_uppercase()
        .chars()
        .map(|c| {
            if c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_' {
                c
            } else {
                '_'
            }
        })
        .collect();
    if r.is_empty() {
        "RELATED_TO".into()
    } else {
        r
    }
}

/// The stored properties of a node or edge: every field not starting with `_` whose value is a
/// string, a 64-bit integer, a float or a boolean, in file order.
fn props(attrs: &Attrs) -> Props {
    attrs
        .iter()
        .filter(|(k, _)| !k.starts_with('_'))
        .filter_map(|(k, v)| {
            let p = match v {
                Attr::Str(s) => Prop::Str(s.to_string()),
                Attr::Bool(b) => Prop::Bool(*b),
                Attr::Int(i) => Prop::Int(*i),
                Attr::Float(f) => Prop::Float(*f),
                // Null, lists, objects, and integers beyond 64 bits (Graphify's push fails on
                // those; dijkstral skips them).
                Attr::Null | Attr::Json(_) => return None,
            };
            Some((k.to_string(), p))
        })
        .collect()
}

pub struct PushNode {
    pub id: String,
    /// The node's properties followed by `id`.
    pub props: Props,
}

pub struct PushEdge {
    pub source: String,
    pub target: String,
    pub props: Props,
}

/// What `--push` loads, grouped so each group is one statement shape.
pub struct PushPlan {
    /// Every node label, sorted (one index each).
    pub labels: Vec<String>,
    /// Nodes by label, in node order within a label.
    pub nodes: BTreeMap<String, Vec<PushNode>>,
    /// Edges by (source label, type, target label), in `G.edges()` order within a group.
    pub edges: BTreeMap<(String, String, String), Vec<PushEdge>>,
    pub node_count: usize,
    pub edge_count: usize,
}

pub fn push_plan(g: &NxGraph) -> PushPlan {
    let labels_of: Vec<String> = g
        .nodes
        .iter()
        .map(|n| push_label(n.attrs.get("file_type")))
        .collect();
    let mut nodes: BTreeMap<String, Vec<PushNode>> = BTreeMap::new();
    for (n, label) in g.nodes.iter().zip(&labels_of) {
        let mut p = props(&n.attrs);
        p.retain(|(k, _)| k != "id");
        p.push(("id".into(), Prop::Str(n.id.clone())));
        nodes.entry(label.clone()).or_default().push(PushNode {
            id: n.id.clone(),
            props: p,
        });
    }
    let mut edges: BTreeMap<(String, String, String), Vec<PushEdge>> = BTreeMap::new();
    for (_, _, e) in g.edge_walk() {
        let edge = &g.edges[e as usize];
        let key = (
            labels_of[edge.source as usize].clone(),
            push_type(edge.attrs.get("relation")),
            labels_of[edge.target as usize].clone(),
        );
        edges.entry(key).or_default().push(PushEdge {
            source: g.nodes[edge.source as usize].id.clone(),
            target: g.nodes[edge.target as usize].id.clone(),
            props: props(&edge.attrs),
        });
    }
    PushPlan {
        labels: nodes.keys().cloned().collect(),
        nodes,
        edges,
        node_count: g.nodes.len(),
        edge_count: g.edges.len(),
    }
}

/// A label or type as a Cypher identifier. Names are `[A-Za-z0-9_]` only, so backticks always
/// suffice.
pub fn quoted(name: &str) -> String {
    debug_assert!(name.chars().all(ascii_word));
    format!("`{name}`")
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde::Deserialize;
    use serde_json::{json, Value};

    fn attr(v: Value) -> Attr {
        Attr::deserialize(v).unwrap()
    }

    #[test]
    fn capitalize_like_python() {
        assert_eq!(capitalize("code file"), "Code file");
        assert_eq!(capitalize("CONCEPT"), "Concept");
        assert_eq!(capitalize("ß"), "Ss");
        assert_eq!(capitalize("ﬀx"), "Ffx");
        assert_eq!(capitalize("ŉa"), "ʼNa");
        assert_eq!(capitalize("xİ\u{212A}"), "Xi\u{307}k");
        assert_eq!(capitalize(""), "");
    }

    #[test]
    fn file_names_match_graphify() {
        let l = |v: Value| file_label(Some(&attr(v)));
        assert_eq!(file_label(None), "Unknown");
        assert_eq!(l(json!("")), "Unknown");
        assert_eq!(l(json!("  ")), "Entity");
        assert_eq!(l(json!("9abc")), "Entity");
        assert_eq!(l(json!("_lead")), "Entity");
        assert_eq!(l(json!("ünï")), "n");
        assert_eq!(l(json!("ß")), "Ss");
        assert_eq!(l(json!("c++")), "C");
        assert_eq!(l(json!("x_y")), "X_y");
        assert_eq!(l(json!("élan")), "lan");
        let t = |v: Value| file_type(Some(&attr(v)));
        assert_eq!(file_type(None), "RELATES_TO");
        assert_eq!(t(json!("has-part.x")), "HASPARTX");
        assert_eq!(t(json!("ünï")), "N");
        assert_eq!(t(json!("ß")), "SS");
        assert_eq!(t(json!("1starts_digit")), "RELATES_TO");
        assert_eq!(t(json!("_x")), "RELATES_TO");
        assert_eq!(t(json!("imports_from")), "IMPORTS_FROM");
    }

    #[test]
    fn push_names_match_graphify() {
        let l = |v: Value| push_label(Some(&attr(v)));
        assert_eq!(push_label(None), "Entity");
        assert_eq!(l(json!("")), "Entity");
        assert_eq!(l(json!("_lead")), "_lead");
        assert_eq!(l(json!("ünï")), "n");
        let t = |v: Value| push_type(Some(&attr(v)));
        assert_eq!(push_type(None), "RELATED_TO");
        assert_eq!(t(json!("")), "RELATED_TO");
        assert_eq!(t(json!("has-part.x")), "HAS_PART_X");
        assert_eq!(t(json!("ünï")), "_N_");
        assert_eq!(t(json!("calls\n")), "CALLS_");
        assert_eq!(t(json!("ﬀ")), "FF");
        assert_eq!(
            t(json!("rel`); MATCH (n) DETACH DELETE n //")),
            "REL____MATCH__N__DETACH_DELETE_N___"
        );
    }

    #[test]
    fn escapes_cypher_strings() {
        let mut s = String::new();
        escape("it's \"q\" \\ \n\r\0\u{7}\ttab \u{2028}", &mut s);
        assert_eq!(s, "it\\'s \"q\" \\\\ \ttab \u{2028}");
    }
}
